INSERT INTO agent_pending_input (
    pending_id, run_id, source_component, pending_type, input_mode, status, question,
    options_ref, answer_schema_ref, continuation_ref, user_answer_ref, created_at, answered_at, expires_at
) VALUES (
    #{pendingId}, #{runId}, #{sourceComponent}, #{pendingType}, #{inputMode}, #{status}, #{question},
    #{optionsRef}, #{answerSchemaRef}, #{continuationRef}, #{userAnswerRef}, #{createdAt}, #{answeredAt}, #{expiresAt}
)

mapper.update:
UPDATE agent_pending_input
SET status = 'ANSWERED', user_answer_ref = #{userAnswerRef}, answered_at = NOW()
WHERE pending_id = #{pendingId}
  AND run_id = #{runId}
  AND status = 'PENDING'
  AND (expires_at IS NULL OR expires_at > NOW())

UPDATE agent_pending_input
SET status = 'CANCELLED', answered_at = NOW()
WHERE pending_id = #{pendingId}
  AND run_id = #{runId}
  AND status = 'PENDING'
  AND (expires_at IS NULL OR expires_at > NOW())
